from collections import defaultdict
from datetime import timedelta
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")
DUPLICATE_WINDOW_DAYS = 2


def _exact(amount):
    # Go through str() so binary float artifacts (e.g. 0.1) don't leak into sums.
    return Decimal(str(amount))


def _in_month(day, month):
    return f"{day.year:04d}-{day.month:02d}" == month


def summarize(transactions, month):
    """Map category -> net total for the calendar month given as "YYYY-MM".

    Refunds (negative amounts) reduce the total. Categories whose exact net
    total is zero are omitted. Totals are rounded to 2 decimals.
    """
    totals = defaultdict(Decimal)
    for t in transactions:
        if _in_month(t.day, month):
            totals[t.category] += _exact(t.amount)
    return {
        category: float(total.quantize(CENT, rounding=ROUND_HALF_UP))
        for category, total in totals.items()
        if total != 0
    }


def find_duplicates(transactions):
    """Return (earlier_id, later_id) pairs that look like duplicate charges.

    A pair shares payee and amount, its dates are at most 2 days apart
    (inclusive), and neither is a refund. The list is sorted by the earlier
    transaction's date, then its id.
    """
    candidates = [t for t in transactions if t.amount > 0]
    pairs = []
    for i, a in enumerate(candidates):
        for b in candidates[i + 1:]:
            if a.payee != b.payee or _exact(a.amount) != _exact(b.amount):
                continue
            if abs((a.day - b.day).days) > DUPLICATE_WINDOW_DAYS:
                continue
            earlier, later = sorted((a, b), key=lambda t: (t.day, t.id))
            pairs.append((earlier, later))
    pairs.sort(key=lambda p: (p[0].day, p[0].id))
    return [(earlier.id, later.id) for earlier, later in pairs]

