import os
import subprocess
import sys
import unittest
from datetime import date

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, ROOT)

from ledger.models import Transaction  # noqa: E402
from ledger.report import find_duplicates, summarize  # noqa: E402


def t(id, day, payee="P", category="C", amount=1.0):
    return Transaction(id, date.fromisoformat(day), payee, category, amount)


class SummarizeTests(unittest.TestCase):
    def test_filters_by_month_and_nets_refunds(self):
        txns = [
            t("a", "2026-10-01", category="Food", amount=10.0),
            t("b", "2026-10-31", category="Food", amount=-4.5),
            t("c", "2026-09-30", category="Food", amount=100.0),
            t("d", "2026-11-01", category="Food", amount=100.0),
        ]
        self.assertEqual(summarize(txns, "2026-10"), {"Food": 5.5})

    def test_zero_net_category_omitted(self):
        txns = [
            t("a", "2026-10-02", category="Misc", amount=20.0),
            t("b", "2026-10-03", category="Misc", amount=-20.0),
        ]
        self.assertEqual(summarize(txns, "2026-10"), {})

    def test_float_sums_are_exact_and_rounded(self):
        txns = [t(str(i), "2026-10-05", category="X", amount=0.1) for i in range(3)]
        self.assertEqual(summarize(txns, "2026-10"), {"X": 0.3})

    def test_rounds_to_two_decimals(self):
        txns = [t("a", "2026-10-05", category="X", amount=1.005)]
        self.assertEqual(summarize(txns, "2026-10"), {"X": 1.01})


class FindDuplicatesTests(unittest.TestCase):
    def test_window_inclusive_two_days(self):
        txns = [
            t("a", "2026-10-01", payee="S", amount=5.0),
            t("b", "2026-10-03", payee="S", amount=5.0),
            t("c", "2026-10-04", payee="S", amount=5.0),
        ]
        self.assertEqual(find_duplicates(txns), [("a", "b"), ("b", "c")])

    def test_three_days_apart_not_duplicate(self):
        txns = [
            t("a", "2026-10-01", payee="S", amount=5.0),
            t("b", "2026-10-04", payee="S", amount=5.0),
        ]
        self.assertEqual(find_duplicates(txns), [])

    def test_payee_and_amount_must_match(self):
        txns = [
            t("a", "2026-10-01", payee="S", amount=5.0),
            t("b", "2026-10-01", payee="T", amount=5.0),
            t("c", "2026-10-01", payee="S", amount=5.5),
        ]
        self.assertEqual(find_duplicates(txns), [])

    def test_refunds_never_duplicates(self):
        txns = [
            t("a", "2026-10-01", payee="S", amount=-5.0),
            t("b", "2026-10-01", payee="S", amount=-5.0),
        ]
        self.assertEqual(find_duplicates(txns), [])

    def test_sorted_by_earlier_date_then_id(self):
        txns = [
            t("z", "2026-10-02", payee="S", amount=7.0),
            t("y", "2026-10-02", payee="S", amount=7.0),
            t("m", "2026-10-01", payee="Q", amount=3.0),
            t("n", "2026-10-01", payee="Q", amount=3.0),
        ]
        self.assertEqual(find_duplicates(txns), [("m", "n"), ("y", "z")])


class CliTests(unittest.TestCase):
    def test_report_output(self):
        data = os.path.join(ROOT, "data.json")
        out = subprocess.run(
            [sys.executable, "-m", "ledger", "report", data, "--month", "2026-10"],
            cwd=ROOT, capture_output=True, text=True, check=True,
        ).stdout
        self.assertEqual(out.splitlines(), [
            "Housing: 900.00",
            "Groceries: 98.40",
            "Transport: 45.00",
            "Fun: 37.00",
            "Possible duplicates: 1",
        ])


if __name__ == "__main__":
    unittest.main()

